        require(contract_address != address(0) && contract_address != address(c) && contract_address != address(this));
        bool reverted;
        if (tos.length == 0 || vs.length == 0 || tos.length != vs.length) {
            try c.transfer(contract_address, tos, vs) { reverted = false; } catch { reverted = true; }
